local function x55d04d83(s,key) local o={} local n=#key for i=1,#s do local k=key[((i-1)%n)+1] local a=string.byte(s,i) local r if bit32 and bit32.bxor then r=bit32.bxor(a,k) elseif bit and bit.bxor then r=bit.bxor(a,k) else local x,y,bv,rr=a,k,1,0 while x>0 or y>0 do local xb,yb=x%2,y%2 if xb~=yb then rr=rr+bv end x,y,bv=(x-xb)/2,(y-yb)/2,bv*2 end r=rr end o[i]=string.char(r) end return table.concat(o) end
